// FUNCTION: BFME2 0x0018F3F0 size=80 name=?Get_Transform@HCompressedAnimClass@@UBEXAAVMatrix3D@@HM@Z evidence=N:ledger tier=B hypothesis:cohesion
void HCompressedAnimClass::Get_Transform(Matrix3D &mtx, int pivot, float frame) const
{
	// Like HRawAnimClass::Get_Transform (0x0018DF20) the slot stores the orientation in the first four words and the translation in
	// the next three instead of building a matrix.
	if (!Get_Orientation(*(Quaternion *)&mtx.Row[0], pivot, frame)) {
		((Quaternion *)&mtx.Row[0])->Make_Identity();
	}
	Get_Translation(*(Vector3 *)&mtx.Row[1], pivot, frame);
}


// FUNCTION: BFME2 0x0018F440 size=70 name=?Get_Visibility@HCompressedAnimClass@@UAE_NHM@Z evidence=N:ledger tier=B hypothesis:cohesion
bool HCompressedAnimClass::Get_Visibility(int pivot, float frame)
{
	TimeCodedBitChannelClass *channel;
	if (Channels != 0) {
		channel = Channels[pivot].Visibility;
	} else {
		channel = NodeMotion[pivot].Visibility;
	}
	if (channel != 0) {
		return channel->Get_Bit((int)frame) == 1;
	}
	return true;
}

// FUNCTION: BFME2 0x0018F490 size=108 name=?Is_Node_Motion_Present@HCompressedAnimClass@@UAE_NH@Z evidence=N:ledger tier=B hypothesis:cohesion
bool HCompressedAnimClass::Is_Node_Motion_Present(int pivot)
{
	if (Channels != 0) {
		for (int i = 0; i < 5; i++) {
			if (Channels[pivot].Motion[i] != 0) {
				return true;
			}
		}
		if (Channels[pivot].Visibility != 0) return true;
	} else {
		if (NodeMotion[pivot].tc.X != 0) return true;
		if (NodeMotion[pivot].tc.Y != 0) return true;
		if (NodeMotion[pivot].tc.Z != 0) return true;
		if (NodeMotion[pivot].tc.Q != 0) return true;
		if (NodeMotion[pivot].Visibility != 0) return true;
	}
	return false;
}

