// FUNCTION: BFME2 0x0018F7B0 size=158 name=?Get_Channel_Memory_Usage@NodeCompressedMotionStruct@@QAEHXZ evidence=N:ledger tier=B hypothesis:cohesion
int NodeCompressedMotionStruct::Get_Channel_Memory_Usage()
{
	int size = sizeof(NodeCompressedMotionStruct);

	switch (Flavor) {
	case ANIM_FLAVOR_TIMECODED:
		if (tc.X) size = tc.X->Get_Channel_Memory_Usage() + sizeof(NodeCompressedMotionStruct);
		if (tc.Y) size += tc.Y->Get_Channel_Memory_Usage();
		if (tc.Z) size += tc.Z->Get_Channel_Memory_Usage();
		if (tc.Q) size += tc.Q->Get_Channel_Memory_Usage();
		break;
	case ANIM_FLAVOR_ADAPTIVE_DELTA:
		if (ad.X) size = ad.X->Get_Channel_Memory_Usage() + sizeof(NodeCompressedMotionStruct);
		if (ad.Y) size += ad.Y->Get_Channel_Memory_Usage();
		if (ad.Z) size += ad.Z->Get_Channel_Memory_Usage();
		if (ad.Q) size += ad.Q->Get_Channel_Memory_Usage();
		break;
	}

	if (Visibility) size += Visibility->Get_Channel_Memory_Usage();
	return size;
}

